import glob, xml.etree.ElementTree as ET
rows=[]
for path in sorted(glob.glob('**/build/test-results/**/*.xml', recursive=True)):
    if '/binary/' in path: continue
    try:
        root=ET.parse(path).getroot()
    except Exception:
        continue
    if root.tag != 'testsuite':
        continue
    rows.append((path,int(root.attrib.get('tests','0')),int(root.attrib.get('failures','0')),int(root.attrib.get('errors','0')),int(root.attrib.get('skipped','0'))))
print('files',len(rows),'tests',sum(r[1] for r in rows),'failures',sum(r[2] for r in rows),'errors',sum(r[3] for r in rows),'skipped',sum(r[4] for r in rows))
for r in rows:
    if r[2] or r[3] or r[4] or any(s in r[0] for s in ['JdbcStrategyRepository','CleanMigration','StrategyAdapterDependency','BootCompatibilitySmokeTest']):
        print(*r)
